nta.declaration:
// Place global declarations here.
const int N = 25; // number of nodes in this simulation. 
const int nodeList[4] = {1, 3, 5, 25}; // target nodes list.

chan UAVChannel[N+1], loc_msg, rep_msg, ack_msg[N+1], error_msg[N+1];
broadcast chan find_msg, err_msg;
int i, p_nodes, q_nodes = 0;
int current_id, current_pid, init_neighbours;
clock x;
bool passing = true;

// neighbour array
typedef struct
{
    int node1;
    int node2;
    int node3;
    int node4;
} neighbour_t;

void setNeighbours(neighbour_t &neighbours, int node1, int node2, int node3, int node4) {
    neighbours.node1 = node1;
    neighbours.node2 = node2;
    neighbours.node3 = node3;
    neighbours.node4 = node4;
}

neighbour_t currentNeighbours;

// Store current node id. 
void setCurrentID(int id) {
    current_id = id;
}

// Store current node's neighbours.
void setCurrentNeighbours(neighbour_t neighbours){
    currentNeighbours = neighbours;
}

// Check whether the node is in the range of broadcast.
bool checkBroadcast(int id){
    if(id==currentNeighbours.node1 || id==currentNeighbours.node2 || id==currentNeighbours.node3 || id==currentNeighbours.node4){
        return true;
    } 
    return false;
}

// Store current node's parent node.
void setCurrentPID(int id){
    current_pid = id;
}

// Get current node's parent node.
int getCurrentPID(){
    return current_pid;
}

// Get initial node's id.
int getInitID(){
    return nodeList[i];
}

// Tranverse every initial node id in the nodeList.
void nextNode(){
    if(i<2){
        i+=1;
    } else {
        i = 0;
    }
}

// Get current initial node id.
int getInitNode(){
    return nodeList[i];
}

// Get current tid.
int getTid(){
    return nodeList[i+1];
} 

// Check and set how many neibour nodes does the initial node have.
void setInitNeighbours(int n_count){
    init_neighbours = n_count;
}

// Return the value of p_nodes.
int getPNodes(){
    return p_nodes;
}

// Return the value of q_nodes.
int getQNodes(){
    return q_nodes;
}

// Return the value of init_neighbours.
int getInitNeighbours(){
    return init_neighbours;
}

// Reset the value of p_nodes and q_nodes after one iteration of porcessFindNode finished during the UAV is moving.
void resetPQ(){
    p_nodes = 0;
    q_nodes = 0;
}

template.declaration:
// Place local declarations here.
bool initial, find = false;
int msg_list[4];
int nextIndex = 0;
int pid, count, neighboursCount = 0;
neighbour_t neighbours;


// Set the node as initial node that start the find process and directly communicate with the UAV.
void setInit(){
    initial = true;
}

// Get whether this node is the initial node.
bool getInit(){
    return initial;
}

// Set the node as find after this node participated in the finding process.
void setFind(){
    find = true;
}

// Get whether the node has been participated in the finding process.
bool getFind(){
    return find;
}

// Set this node's parent node.
void setPID(int id){
    pid = id;
}

// get this node's parent node.
int getPID(){
    return pid;
}

// Add messages received into the list. 1 refers to ack_msg and 0 refers to error_msg.
void addMsg(int msg){
    count+=1;
    if(nextIndex <= 3){
        msg_list[nextIndex] = msg;
        nextIndex++;
    }
}

// Check whether there is ack_msg in the list.
bool findAckMsg(int msg) {
    for(i : int[0,3]) {
        if(msg_list[i] == msg) {
            return true;
        }
    }
    return false;
}

// reset every nodes.
void reset(){
    initial = false;
    find = false;
    nextIndex = 0;
    addMsg(0);
    addMsg(0);
    addMsg(0);
    nextIndex = 0;
    pid = id;
    neighboursCount = 0;
    count = 0;
}

// Check how many neighbour nodes does this node have.
void checkNeighbours(){
    if(neighbours.node1!=0){
        neighboursCount+=1;
    } 
    if(neighbours.node2!=0){
        neighboursCount+=1;
    } 
    if(neighbours.node3!=0){
        neighboursCount+=1;
    } 
    if(neighbours.node4!=0){
        neighboursCount+=1;
    }    
}

// Check how many child nodes does this node have.
int checkCount(){
    if(initial==true){
        return neighboursCount;
    } else {
        return neighboursCount-1;
    }
}

// return the count of neighbour nodes.
int getneighboursCount(){
    return neighboursCount;
}

// Check whether all second level nodes have participated in the processFindNode and have sent back error_msg or ack_msg back to their parent nodes.
bool checkPoint(){
    if(count==checkCount()){
        return true;
    } else if(count==checkCount()-1 && getQNodes()==getPNodes()+getInitNeighbours() && initial==false){
        return true;
    } else if(count==checkCount()-2 && getQNodes()==getPNodes()+getInitNeighbours() && initial==false){
        return true;
    } else {
        return false;
    }
}

